def get_effective_dashboard_data_path():
    """Return explicit, configured, or bundled dashboard_data.json path."""
    return (
        app.config.get('DASHBOARD_DATA_FILE')
        or os.environ.get('DASHBOARD_DATA_FILE')
        or os.path.join(BASE_DIR, 'dashboard_data.json')
    )


def is_generation_configured() -> bool:
    """Check if generation cache mode is explicitly configured."""
    return bool(app.config.get('GENERATION_CACHE_ROOT') or os.environ.get('GENERATION_CACHE_ROOT'))


def is_remote_generation_configured() -> bool:
    """Check if remote generation polling mode is explicitly configured."""
    enabled_val = app.config.get('GENERATION_REMOTE_ENABLED') or os.environ.get('GENERATION_REMOTE_ENABLED')
    is_enabled = str(enabled_val).lower() in ('true', '1', 'yes')
    has_endpoint = bool(app.config.get('GENERATION_REMOTE_ENDPOINT') or os.environ.get('GENERATION_REMOTE_ENDPOINT'))
    has_token = bool(app.config.get('GENERATION_READ_TOKEN') or os.environ.get('GENERATION_READ_TOKEN'))
    has_cache = is_generation_configured()
    return is_enabled and has_endpoint and has_token and has_cache


def get_generation_reader():
    """Get or create singleton GenerationReader for app."""
    cache_root = app.config.get('GENERATION_CACHE_ROOT') or os.environ.get('GENERATION_CACHE_ROOT')
    if not cache_root:
        return None
    if getattr(app, '_generation_reader', None) is not None:
        if getattr(app, '_generation_reader_root', None) == str(cache_root):
            return app._generation_reader
    try:
        from generation_reader import GenerationReader
        reader = GenerationReader(cache_root)
        app._generation_reader = reader
        app._generation_reader_root = str(cache_root)
        return reader
    except Exception as e:
        app.logger.error(f"Failed to initialize GenerationReader: {e}")
        return None


def get_remote_syncer():
    """Get or create singleton RemoteGenerationSyncer if configured."""
    if not is_remote_generation_configured():
        return None
    cache_root = app.config.get('GENERATION_CACHE_ROOT') or os.environ.get('GENERATION_CACHE_ROOT')
    if getattr(app, '_remote_syncer', None) is not None:
        if getattr(app, '_remote_syncer_root', None) == str(cache_root):
            return app._remote_syncer
    try:
        from generation_remote_reader import RemoteGenerationClient, RemoteGenerationSyncer
        endpoint = app.config.get('GENERATION_REMOTE_ENDPOINT') or os.environ.get('GENERATION_REMOTE_ENDPOINT')
        token = app.config.get('GENERATION_READ_TOKEN') or os.environ.get('GENERATION_READ_TOKEN')
        allow_loopback = str(app.config.get('GENERATION_ALLOW_LOOPBACK') or os.environ.get('GENERATION_ALLOW_LOOPBACK', '')).lower() in ('true', '1', 'yes')
        timeout = int(app.config.get('GENERATION_POLL_TIMEOUT') or os.environ.get('GENERATION_POLL_TIMEOUT', '15'))

        client = RemoteGenerationClient(
            endpoint=endpoint,
            token=token,
            enabled=True,
            allow_loopback=allow_loopback,
            timeout=timeout
        )
        gen_reader = get_generation_reader()
        poll_interval = float(app.config.get('GENERATION_POLL_INTERVAL') or os.environ.get('GENERATION_POLL_INTERVAL', '30'))
        failure_backoff = float(app.config.get('GENERATION_FAILURE_BACKOFF') or os.environ.get('GENERATION_FAILURE_BACKOFF', '10'))
        syncer = RemoteGenerationSyncer(
            client=client,
            cache_root=Path(cache_root),
            local_reader=gen_reader,
            poll_interval=poll_interval,
            failure_backoff=failure_backoff
        )
        app._remote_syncer = syncer
        app._remote_syncer_root = str(cache_root)
        return syncer
    except Exception as e:
        app.logger.error(f"Failed to initialize RemoteGenerationSyncer: {e}")
        return None


def _safe_ascii_header(val, limit=200):
    clean = str(val or '').replace('\r', ' ').replace('\n', ' ')
    return clean.encode('ascii', 'replace').decode('ascii')[:limit]


@app.route('/dashboard_data.json')
@app.route('/api/dashboard-data')
def serve_dashboard_data():
    if is_generation_configured():
        gen_reader = get_generation_reader()
        if gen_reader is None:
            return jsonify({'error': '유효한 세대 데이터를 읽을 수 없습니다 (모듈 초기화 실패)'}), 503

        # If remote syncer is active, perform controlled sync_if_needed()
        remote_syncer = get_remote_syncer()
        remote_sync_failed = False
        if remote_syncer is not None:
            sync_ok, sync_info = remote_syncer.sync_if_needed()
            if not sync_ok:
                remote_sync_failed = True
                gen_reader._last_error = f"원격 세대 동기화 실패: {sync_info}"

        rec = gen_reader.resolve()
        if rec is None:
            err_msg = gen_reader._last_error or '유효한 세대 데이터가 아직 준비되지 않았습니다'
            resp = jsonify({'error': f'유효한 세대 데이터가 없습니다: {err_msg}'})
            if remote_syncer is not None:
                resp.headers['X-Remote-Sync-Status'] = 'failed'
                if remote_syncer.last_sync_error:
                    resp.headers['X-Remote-Sync-Error'] = _safe_ascii_header(remote_syncer.last_sync_error)
            return resp, 503

        # If remote sync failed, mark retained fallback on rec to trigger warning UI
        if remote_sync_failed:
            rec.is_retained_fallback = True
            rec.last_error = remote_syncer.last_sync_error if remote_syncer else '원격 동기화 실패'

        status_info = gen_reader.get_status_info(rec)
        if remote_syncer is not None:
            status_info['last_success_time'] = remote_syncer.last_success_time
            status_info['last_sync_time'] = remote_syncer.last_sync_time
            status_info['consecutive_failures'] = remote_syncer.consecutive_failures
            status_info['poll_interval'] = remote_syncer.poll_interval
            status_info['failure_backoff'] = remote_syncer.failure_backoff

        data = copy.deepcopy(rec.dashboard_data)
        data['_generation'] = status_info
        resp_body = json.dumps(data, ensure_ascii=False)
        response = Response(resp_body, mimetype='application/json')
        response.headers['Cache-Control'] = 'no-store'
        response.headers['X-Generation-Revision'] = rec.revision
        response.headers['X-Source-As-Of'] = rec.source_as_of
        response.headers['X-Generation-Status'] = 'retained' if rec.is_retained_fallback else 'active'
        if remote_syncer is not None:
            response.headers['X-Remote-Sync-Status'] = 'failed' if remote_sync_failed else 'ok'
            if remote_syncer.last_success_time:
                response.headers['X-Remote-Last-Success'] = str(int(remote_syncer.last_success_time))
            if remote_syncer.last_sync_error:
                response.headers['X-Remote-Sync-Error'] = _safe_ascii_header(remote_syncer.last_sync_error)
        return response

    path = get_effective_dashboard_data_path()
    if not os.path.isfile(path):
        return jsonify({'error': '대시보드 데이터가 아직 생성되지 않았습니다'}), 404
    response = send_file(path, mimetype='application/json', max_age=0)
    response.headers['Cache-Control'] = 'no-store'
    return response


def get_effective_automation_status_path():
    """
    Resolve automation collection status JSON file path for 20-year veteran food MD.
    Prioritizes explicit AUTOMATION_STATUS_PATH environment variable or app.config,
    then standard flat/bundled BASE_DIR/automation_status.json only.
    Arbitrary scratch candidate exploration is strictly forbidden.
    """
    env_path = os.environ.get('AUTOMATION_STATUS_PATH') or app.config.get('AUTOMATION_STATUS_PATH')
    if env_path:
        return env_path if os.path.isfile(env_path) else None

    prod_path = os.path.join(BASE_DIR, 'automation_status.json')
    if os.path.isfile(prod_path):
        return prod_path
    return None


@app.route('/api/automation-status')
def serve_automation_status():
    """
    Serve public machine-readable channel collection status for 20-year veteran food MD.
    Strictly sanitizes and never exposes raw tokens, passwords, full bank accounts, or private Drive URLs.
    Validates field types, lengths, and state enums.
    """
    path = get_effective_automation_status_path()
    if not path or not os.path.isfile(path):
        return jsonify({
            'version': 1,
            'available': False,
            'requested_date': None,
            'attempted_at': None,
            'run_status': 'not_configured',
            'publication_status': 'not_attempted',
            'channels': {}
        }), 200

    try:
        with open(path, 'r', encoding='utf-8') as f:
            raw_data = json.load(f)
    except Exception:
        return jsonify({
            'version': 1,
            'available': False,
            'error': '상태 파일을 불러올 수 없습니다.',
            'channels': {}
        }), 500

    VALID_CHANNEL_STATUSES = {
        'success', 'partial', 'auth_required', 'failed', 'not_collected',
        'retained', 'collected', 'collected_zero', 'unknown'
    }
    VALID_RUN_STATUSES = {
        'not_configured', 'not_attempted', 'awaiting_sources', 'candidate_ready',
        'published_verified', 'published_render', 'already_completed', 'failed',
        'partial', 'retry_exhausted'
    }

    def _clean_str(v, max_len=64):
        if not isinstance(v, str):
            return None
        s = v.strip()
        return s[:max_len] if s else None

    def _clean_int(v):
        if isinstance(v, int) and not isinstance(v, bool) and 0 <= v <= 10_000_000:
            return v
        return None

    def _clean_bool(v):
        return v is True

    clean_channels = {}
    for ch_name, ch_info in raw_data.get('channels', {}).items():
        if not isinstance(ch_info, dict) or not isinstance(ch_name, str) or len(ch_name) > 32:
            continue
        raw_st = str(ch_info.get('status') or '').lower().strip()
        clean_st = raw_st if raw_st in VALID_CHANNEL_STATUSES else 'unknown'

        clean_channels[ch_name] = {
            'status': clean_st,
            'source_as_of': _clean_str(ch_info.get('source_as_of'), 16),
            'attempted_at': _clean_str(ch_info.get('attempted_at'), 35),
            'success_at': _clean_str(ch_info.get('success_at'), 35),
            'requested_period': ch_info.get('requested_period') if isinstance(ch_info.get('requested_period'), dict) else None,
            'confirmed_period': ch_info.get('confirmed_period') if isinstance(ch_info.get('confirmed_period'), dict) else None,
            'processed_count': _clean_int(ch_info.get('processed_count')),
            'included_count': _clean_int(ch_info.get('included_count')),
            'excluded_count': _clean_int(ch_info.get('excluded_count')),
            'pending_count': _clean_int(ch_info.get('pending_count')),
            'count_reason': _clean_str(ch_info.get('count_reason'), 64),
            'error_code': _clean_str(ch_info.get('error_code'), 64),
            'api_error_code': _clean_str(ch_info.get('api_error_code'), 64),
            'is_business_zero_verified': _clean_bool(ch_info.get('is_business_zero_verified')) or _clean_bool(ch_info.get('business_zero_verified')),
            'account_scope_verified': _clean_bool(ch_info.get('account_scope_verified')),
            'completion_verified': _clean_bool(ch_info.get('completion_verified')),
        }

    run_st = str(raw_data.get('run_status') or '').lower().strip()
    clean_run_st = run_st if run_st in VALID_RUN_STATUSES else 'not_attempted'
    pub_st = str(raw_data.get('publication_status') or '').lower().strip()
    clean_pub_st = pub_st if pub_st in VALID_RUN_STATUSES else 'not_attempted'

    last_success = raw_data.get('last_success')
    clean_last_success = None
    if isinstance(last_success, dict):
        clean_last_success = {
            'revision': _clean_str(last_success.get('revision'), 64),
            'requested_date': _clean_str(last_success.get('requested_date'), 16),
            'source_as_of': _clean_str(last_success.get('source_as_of'), 16),
            'verified_at': _clean_str(last_success.get('verified_at'), 35),
            'external_status_verified': _clean_bool(last_success.get('external_status_verified')),
        }

    resp_data = {
        'version': 1,
        'available': True,
        'requested_date': _clean_str(raw_data.get('requested_date'), 16),
        'attempted_at': _clean_str(raw_data.get('attempted_at'), 35),
        'run_status': clean_run_st,
        'publication_status': clean_pub_st,
        'network_attempted': _clean_bool(raw_data.get('network_attempted', False)),
        'last_success': clean_last_success,
        'channels': clean_channels,
        'observation_only': _clean_bool(raw_data.get('observation_only', False)),
    }
    resp = Response(json.dumps(resp_data, ensure_ascii=False), mimetype='application/json')
    resp.headers['Cache-Control'] = 'no-store'
    return resp


def get_pnl_search_context():
    """
    Resolve Excel PnL directory context.
    Returns (explicit_dir, fallback_dirs).
    If an explicit or bundled release directory exists, explicit_dir is set and fallback_dirs is empty (no fallback).
    """
    # 1. Configured or environment path has highest priority
    cfg_dir = app.config.get('PNL_OUTPUT_DIR') or os.environ.get('PNL_OUTPUT_DIR')
    if cfg_dir:
        # 명시적 설정이 존재하는 경우 디렉터리 존재 여부와 무관하게 검색 범위를 고정 (fallback 절대 금지)
        return cfg_dir, []

    # 2. Bundled output_excel in flat deployment root (BASE_DIR/output_excel)
    flat_dir = os.path.join(BASE_DIR, 'output_excel')
    if os.path.isdir(flat_dir):
        return flat_dir, []

    # 3. Bundled output_excel in nested web_dashboard structure (dirname(BASE_DIR)/output_excel)
    if os.path.basename(BASE_DIR) == 'web_dashboard':
        parent_dir = os.path.join(os.path.dirname(BASE_DIR), 'output_excel')
        if os.path.isdir(parent_dir):
            return parent_dir, []

    # 4. Fallback legacy mode when no explicit release directory is present
    legacy_fallbacks = [
        os.path.join(BASE_DIR, '.cloud_cache/output_excel'),
        os.path.join(os.path.dirname(BASE_DIR), 'output_excel'),
        os.path.join(BASE_DIR, '..', 'output_excel'),
        r'C:\AI\경영관리\output_excel'
    ]
    existing_fallbacks = [d for d in legacy_fallbacks if os.path.isdir(d)]
    return None, existing_fallbacks

_cloud_read_lock = threading.Lock()
_cloud_read_checked = 0.0
cloud_read_state = {'status': 'disabled', 'last_success': '', 'report_date': ''}


def refresh_cloud_files(force=False):
    """Fetch published files on boot/read, retaining last verified data on error."""
    global _cloud_read_checked
    enabled = os.environ.get('CLOUD_READ_ENABLED', '1' if os.environ.get('RENDER') else '0') == '1'
    if not enabled or (app.testing and not app.config.get('TEST_CLOUD_READ')):
        return
    interval = max(5, int(os.environ.get('CLOUD_POLL_SECONDS', '30')))
    if not force and time.monotonic() - _cloud_read_checked < interval:
        return
    if not _cloud_read_lock.acquire(blocking=False):
        return
    try:
        _cloud_read_checked = time.monotonic()
        store = CloudStore(timeout=8)
        if not store.configured:
            cloud_read_state['status'] = 'disabled'
            return
        cache = Path(os.environ.get('CLOUD_CACHE_DIR') or Path(BASE_DIR) / '.cloud_cache')
        result = restore_latest(cache, store)
        cloud_read_state.update(result)
        if result['status'] in ('synced', 'local_newer'):
            # 1. 재고 원천 및 채널 화이트리스트는 항상 클라우드 캐시에서 갱신 (재고 동기화 보존)
            app.config['INVENTORY_RAW_DIR'] = str(cache / 'raw_data/inventory')
            app.config['CHANNEL_WHITELIST_FILE'] = str(cache / 'master_data/오키드상품정보.xlsx')

            # 2. 고정 / 명시적 릴리스 모드 보호:
            # DASHBOARD_DATA_FILE이 환경변수 또는 고정 릴리스 설정으로 명시된 경우 구버전 클라우드 캐시로 덮어쓰지 않음
            explicit_json = os.environ.get('DASHBOARD_DATA_FILE') or (app.config.get('DASHBOARD_DATA_FILE') if app.config.get('FIXED_RELEASE_DATA') else None)
            if explicit_json:
                app.config['DASHBOARD_DATA_FILE'] = explicit_json
            else:
                app.config['DASHBOARD_DATA_FILE'] = str(cache / 'web_dashboard/dashboard_data.json')

            # PNL_OUTPUT_DIR이 환경변수 또는 고정 릴리스 설정으로 명시된 경우 구버전 클라우드 캐시로 덮어쓰지 않음
            explicit_pnl = os.environ.get('PNL_OUTPUT_DIR') or (app.config.get('PNL_OUTPUT_DIR') if app.config.get('FIXED_RELEASE_DATA') else None)
            if explicit_pnl:
                app.config['PNL_OUTPUT_DIR'] = explicit_pnl
            else:
                app.config['PNL_OUTPUT_DIR'] = str(cache / 'output_excel')

            if result['status'] == 'synced':
                cloud_read_state['last_success'] = now_kst().isoformat()
    except Exception:
        cloud_read_state['status'] = 'stale'
        app.logger.warning('Cloud refresh failed; serving last verified local data')
    finally:
        _cloud_read_lock.release()


@app.before_request
def refresh_cloud_on_read():
    if request.method == 'GET' and (request.path in (
            '/', '/share/inventory', '/api/summary', '/api/dashboard-data',
            '/dashboard_data.json', '/api/download-pnl-excel', '/api/export-master-csv')
            or request.path.startswith('/api/export/')):
        refresh_cloud_files()


@app.after_request
def cloud_freshness_headers(response):
    if request.path in ('/api/dashboard-data', '/dashboard_data.json', '/api/summary'):
        response.headers['X-Cloud-Sync-Status'] = cloud_read_state['status']
        response.headers['X-Cloud-Last-Success'] = cloud_read_state['last_success']
    return response


@app.route('/api/download-pnl-excel')
def download_pnl_excel():
    """최신 월간 식품부문 손익결산서 엑셀 다운로드"""
    month = request.args.get('month')
    if month and not re.fullmatch(r'\d{4}-(0[1-9]|1[0-2])', month):
        return jsonify(error='월 형식: YYYY-MM'), 400

    revision = request.args.get('revision')
    if revision and not re.fullmatch(r'[0-9a-fA-F]{12,64}', revision):
        return jsonify(error='유효하지 않은 revision 형식입니다'), 400

    if is_generation_configured():
        gen_reader = get_generation_reader()
        if gen_reader is None:
            return jsonify({'error': '세대 캐시 모듈을 초기화할 수 없습니다'}), 503

        active_rec = gen_reader.resolve()
        if not month:
            if active_rec and getattr(active_rec, 'requested_date', None):
                month = active_rec.requested_date[:7]
            else:
                month = '2026-11'

        excel_bytes = gen_reader.get_excel_bytes(month, revision=revision)
        if excel_bytes is None:
            return jsonify({'error': f'{month} 결산서 엑셀을 찾을 수 없습니다'}), 404

        target_rev = revision if revision else (active_rec.revision if active_rec else '')
        filename = f"{month}_식품부문_손익결산서.xlsx"
        response = send_file(
            io.BytesIO(excel_bytes),
            mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            as_attachment=True,
            download_name=filename
        )
        response.headers['Cache-Control'] = 'no-store'
        response.headers['X-Generation-Revision'] = target_rev
        return response

    explicit_dir, fallback_dirs = get_pnl_search_context()
    target_dirs = [explicit_dir] if explicit_dir else fallback_dirs

    if explicit_dir and not os.path.isdir(explicit_dir):
        return jsonify({'error': f'지정된 결산서 디렉터리를 찾을 수 없습니다: {explicit_dir}'}), 404

    if not target_dirs:
        return jsonify({'error': '월간 손익결산서 엑셀 디렉터리를 찾을 수 없습니다'}), 404

    # Search in target directories
    for d in target_dirs:
        candidates = []
        if os.path.isdir(d):
            for f in os.listdir(d):
                if not f.endswith('.xlsx'):
                    continue
                if month and not f.startswith(month + '_'):
                    continue
                if '손익결산서' in f or 'pnl' in f.lower():
                    full_path = os.path.join(d, f)
                    try:
                        candidates.append((os.path.getmtime(full_path), full_path))
                    except Exception:
                        pass
        if candidates:
            # Sort by mtime descending within the authoritative directory
            candidates.sort(key=lambda x: x[0], reverse=True)
            chosen_file = candidates[0][1]
            return send_file(
                chosen_file,
                as_attachment=True,
                download_name=os.path.basename(chosen_file),
                mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            )
        # If explicit directory was specified but requested month is missing, do NOT fallback to legacy/dev paths!
        if explicit_dir:
            return jsonify({'error': f'{month} 월간 손익결산서 엑셀 파일을 찾을 수 없습니다'}), 404

    return jsonify({'error': '월간 손익결산서 엑셀 파일을 찾을 수 없습니다'}), 404


@app.route('/api/cash-flow/manual-transaction', methods=['POST'])
def add_manual_transaction():
    """타 계좌/수기 입출금 내역 등록 및 대시보드 데이터 반영"""
    try:
        data = request.get_json(force=True) or {}
    except Exception:
        return jsonify({'error': '유효한 JSON 요청이 아닙니다'}), 400

    tx_date = (data.get('date') or '').strip()
    tx_type = (data.get('type') or '').strip().lower()
    partner = (data.get('partner') or '').strip()
    category = (data.get('category') or '').strip()
    memo = (data.get('memo') or '').strip()

    try:
        amount = int(float(data.get('amount') or 0))
    except (ValueError, TypeError):
        return jsonify({'error': '유효한 금액을 입력해주세요'}), 400

    if not tx_date or not re.match(r'^\d{4}-\d{2}-\d{2}$', tx_date):
        return jsonify({'error': '올바른 날짜(YYYY-MM-DD)를 입력해주세요'}), 400
    if tx_type not in ('deposit', 'withdrawal', '입금', '출금'):
        return jsonify({'error': '입금 또는 출금을 선택해주세요'}), 400
    if amount <= 0:
        return jsonify({'error': '금액은 0보다 커야 합니다'}), 400
    if not partner:
        return jsonify({'error': '거래처/적요를 입력해주세요'}), 400

    is_deposit = tx_type in ('deposit', '입금')
    type_code = 'deposit' if is_deposit else 'withdrawal'
    type_label = '입금' if is_deposit else '출금'
    final_category = category or ('수기입금' if is_deposit else '수기출금')

    tx_record = {
        'id': f"manual_{int(time.time()*1000)}",
        'date': tx_date,
        'datetime': f"{tx_date} {datetime.now(KST).strftime('%H:%M:%S')}",
        'type': type_code,
        'type_label': type_label,
        'name': partner,
        'summary': memo or partner,
        'amount': amount,
        'food_status': '식품부문 포함',
        'category': final_category,
        'rule_reason': '수기 등록 거래',
        'is_manual': True
    }

    # 1. manual_transactions.json에 영구 저장
    manual_tx_path = app.config.get('MANUAL_TX_FILE') or MANUAL_TX_FILE
    manual_list = []
    if os.path.isfile(manual_tx_path):
        try:
            with open(manual_tx_path, 'r', encoding='utf-8') as f:
                manual_list = json.load(f)
        except Exception:
            manual_list = []
    manual_list.append(tx_record)
    try:
        with open(manual_tx_path, 'w', encoding='utf-8') as f:
            json.dump(manual_list, f, ensure_ascii=False, indent=2)
    except Exception:
        pass

    # 2. dashboard_data.json에 즉시 반영
    data_path = app.config.get('DASHBOARD_DATA_FILE') or os.environ.get('DASHBOARD_DATA_FILE') or os.path.join(BASE_DIR, 'dashboard_data.json')
    if os.path.isfile(data_path):
        try:
            with open(data_path, 'r', encoding='utf-8') as f:
                d_json = json.load(f)

            cf = d_json.setdefault('cash_flow', {})
            recent = cf.setdefault('recent_transactions', [])
            recent.insert(0, tx_record)
            if 'transactions' in cf:
                cf['transactions'].insert(0, dict(
                    transaction_id=tx_record['id'], date=tx_date, datetime=tx_record['datetime'],
                    customer=partner, description=memo, category=final_category, status='식품부문 포함',
                    deposit_amount=amount if is_deposit else 0,
                    withdrawal_amount=0 if is_deposit else amount))

            tx_month = tx_date[:7]
            monthly = cf.setdefault('monthly', {})
            curr_month = monthly.get('month', tx_month)
            if tx_month == curr_month:
                monthly['transaction_count'] = monthly.get('transaction_count', 0) + 1
                if is_deposit:
                    monthly['deposit_total'] = monthly.get('deposit_total', 0) + amount
                    monthly['net_cash_flow'] = monthly.get('net_cash_flow', 0) + amount
                else:
                    monthly['withdrawal_total'] = monthly.get('withdrawal_total', 0) + amount
                    monthly['net_cash_flow'] = monthly.get('net_cash_flow', 0) - amount

                cats = monthly.setdefault('categories', [])
                cat_match = next((c for c in cats if c.get('category') == final_category), None)
                if cat_match:
                    cat_match['transaction_count'] = cat_match.get('transaction_count', 0) + 1
                    if is_deposit:
                        cat_match['deposit_total'] = cat_match.get('deposit_total', 0) + amount
                    else:
                        cat_match['withdrawal_total'] = cat_match.get('withdrawal_total', 0) + amount
                else:
                    cats.append({
                        'category': final_category,
                        'transaction_count': 1,
                        'deposit_total': amount if is_deposit else 0,
                        'withdrawal_total': 0 if is_deposit else amount
                    })

            with open(data_path, 'w', encoding='utf-8') as f:
                json.dump(d_json, f, ensure_ascii=False, indent=2)

        except Exception as e:
            return jsonify({'success': True, 'warning': f'dashboard_data 반영 경고: {str(e)}', 'transaction': tx_record})

    return jsonify({
        'success': True,
        'message': f"{type_label} {amount:,}원이 성공적으로 등록되었습니다.",
        'transaction': tx_record
    })


EXP_DATE_PATTERN = re.compile(r'(\d{2,4})[.\-/](\d{1,2})[.\-/](\d{1,2})')

def _clean_cell_str(val):
    if val is None or isinstance(val, bool):
        return ""
    if isinstance(val, float):
        if val != val:
            return ""
        if val.is_integer():
            return str(int(val))
    return unicodedata.normalize("NFC", str(val)).strip()

def _clean_id_cell(val):
    s = _clean_cell_str(val)
    if not s:
        return ""
    if re.fullmatch(r"\d+\.0+", s):
        s = s.split(".", 1)[0]
    return s

def _clean_int_cell(val):
    s = _clean_cell_str(val).replace(",", "")
    if not s or s == "-":
        return 0
    if s.isdigit():
        return int(s)
    if re.fullmatch(r"-?\d+(?:\.\d+)?", s):
        try:
            return max(0, int(round(float(s))))
        except Exception:
            return 0
    return 0

def excel_serial_to_datetime(val):
    """Excel 1900 기준 날짜 시리얼(예: 46280.68877314815)을 datetime으로 변환"""
    if val is None or isinstance(val, bool):
        return None
    try:
        if isinstance(val, (int, float)):
            num = float(val)
        else:
            s = str(val).strip()
            if not re.fullmatch(r"\d{5}(?:\.\d+)?", s):
                return None
            num = float(s)
    except Exception:
        return None
    if num != num or num < 20000.0 or num > 80000.0:
        return None
    day_int = int(num)
    frac = num - day_int
    total_secs = int(round(frac * 86400.0))
    return datetime(1899, 12, 30) + timedelta(days=day_int, seconds=total_secs)

def extract_expiry_date(text):
    if not text:
        return None
    m = EXP_DATE_PATTERN.search(str(text))
    if m:
        y, mo, d = m.groups()
        y = int(y)
        if y < 100:
            y += 2000
        try:
            return date(y, int(mo), int(d))
        except Exception:
            return None
    return None

def normalize_date_str(val):
    """YYYY-MM-DD 형식으로 날짜 문자열 정규화 (유효하지 않으면 빈 문자열)"""
    if not val:
        return ""
    s = str(val).strip()
    if not s or s == "__CLEAR__":
        return s
    d = extract_expiry_date(s)
    return d.strftime("%Y-%m-%d") if d else ""

def normalize_gaemi_reg_date(val):
    """개미창고 등록일/일시를 'YYYY-MM-DD HH:MM:SS' 또는 'YYYY-MM-DD'로 정규화 (Excel 시리얼 포함, 비파싱 텍스트는 무손실 보존)"""
    if val is None or isinstance(val, bool):
        return ""
    dt_serial = excel_serial_to_datetime(val)
    if dt_serial is not None:
        has_time = False
        try:
            num = float(val)
            has_time = abs(num - int(num)) > 1e-7 or (dt_serial.hour != 0 or dt_serial.minute != 0 or dt_serial.second != 0)
        except Exception:
            has_time = (dt_serial.hour != 0 or dt_serial.minute != 0 or dt_serial.second != 0)
        return dt_serial.strftime("%Y-%m-%d %H:%M:%S") if has_time else dt_serial.strftime("%Y-%m-%d")

    s = _clean_cell_str(val)
    if not s:
        return ""
    m = re.fullmatch(r"(\d{2,4})[.\-/](\d{1,2})[.\-/](\d{1,2})(?:[ T]+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?", s)
    if m:
        y = int(m.group(1))
        if y < 100:
            y += 2000
        mo, d = int(m.group(2)), int(m.group(3))
        try:
            if m.group(4) is not None:
                dt = datetime(y, mo, d, int(m.group(4)), int(m.group(5) or 0), int(m.group(6) or 0))
                return dt.strftime("%Y-%m-%d %H:%M:%S")
            dt = datetime(y, mo, d)
            return dt.strftime("%Y-%m-%d")
        except Exception:
            return s
    return s

def canonicalize_lot_key(raw_key):
    """개미 로트 키('code||opt[||reg]')를 (canon_full, canon_date_only, canon_opt)로 정규화"""
    s = _clean_cell_str(raw_key)
    if not s:
        return "", "", ""
    parts = s.split("||")
    code_up = _clean_cell_str(parts[0]).upper()
    if not code_up:
        return "", "", ""
    opt_nfc = _clean_cell_str(parts[1]) if len(parts) >= 2 else ""
    reg_raw = _clean_cell_str("||".join(parts[2:])) if len(parts) >= 3 else ""
    canon_opt = f"{code_up}||{opt_nfc}"
    if not reg_raw:
        return canon_opt, canon_opt, canon_opt
    canon_reg = normalize_gaemi_reg_date(reg_raw)
    canon_full = f"{canon_opt}||{canon_reg}" if canon_reg else canon_opt
    date_part = canon_reg[:10] if len(canon_reg) >= 10 and re.match(r"\d{4}-\d{2}-\d{2}", canon_reg) else canon_reg
    canon_date_only = f"{canon_opt}||{date_part}" if date_part else canon_opt
    return canon_full, canon_date_only, canon_opt

def build_lot_override_index(lot_expiry_overrides):
    full_map = {}
    date_only_map = {}
    opt_map = {}
    if not isinstance(lot_expiry_overrides, dict):
        return {"full": full_map, "date_only": date_only_map, "opt": opt_map}
    for k, v in lot_expiry_overrides.items():
        if v is None:
            continue
        cf, cdo, co = canonicalize_lot_key(k)
        if not cf:
            continue
        raw_parts = _clean_cell_str(k).split("||")
        if len(raw_parts) >= 3 and _clean_cell_str("||".join(raw_parts[2:])):
            if cf not in full_map or _clean_cell_str(k) == cf:
                full_map[cf] = v
            cand_has_time = (cf != cdo)
            date_only_map.setdefault(cdo, []).append((cand_has_time, v))
        else:
            if co not in opt_map or _clean_cell_str(k) == co:
                opt_map[co] = v
    return {"full": full_map, "date_only": date_only_map, "opt": opt_map}

def resolve_lot_expiry_override(override_index, lot_expiry_overrides, g_code, item):
    exact_key, opt_key = make_gaemi_lot_keys(g_code, item)
    if not isinstance(lot_expiry_overrides, dict) or not lot_expiry_overrides:
        return None
    # Tier 1: 원시 키 정확 일치
    if exact_key in lot_expiry_overrides:
        return lot_expiry_overrides[exact_key]
    cf, cdo, co = canonicalize_lot_key(exact_key)
    # Tier 2: 정규화(Excel serial / CSV datetime / 대소문자 / NFC) 전체 키 일치
    if cf and cf in override_index["full"]:
        return override_index["full"][cf]
    # Tier 3: 한쪽에 시각(HH:MM:SS)이 생략된 경우에만 날짜 단독 매칭 (동일 일자 다른 로트 혼선 방지)
    item_has_time = bool(cf and cf != cdo)
    cands = override_index["date_only"].get(cdo) or []
    if cands:
        if not item_has_time:
            if len(cands) == 1:
                return cands[0][1]
        else:
            no_time_cands = [val for cand_has_time, val in cands if not cand_has_time]
            if no_time_cands:
                return no_time_cands[0]
    # Tier 4: 옵션 단위 키 일치 (원본 -> 정규화)
    if opt_key in lot_expiry_overrides:
        return lot_expiry_overrides[opt_key]
    if co and co in override_index["opt"]:
        return override_index["opt"][co]
    return None

def _apply_lot_expiry_overrides_locked(overrides, updates):
    if not isinstance(updates, dict):
        return
    for lot_key, exp_val in updates.items():
        k = _clean_cell_str(lot_key)
        if not k:
            continue
        v = str(exp_val or "").strip()
        target_full, _, _ = canonicalize_lot_key(k)
        alias_keys = []
        if target_full and len(k.split("||")) >= 3:
            for existing_k in list(overrides.keys()):
                if existing_k == k:
                    continue
                if len(_clean_cell_str(existing_k).split("||")) >= 3 and canonicalize_lot_key(existing_k)[0] == target_full:
                    alias_keys.append(existing_k)

        if v == "__RESTORE__" or v == "":
            overrides.pop(k, None)
            for ak in alias_keys:
                overrides.pop(ak, None)
        elif v == "__CLEAR__":
            for ak in alias_keys:
                overrides.pop(ak, None)
            overrides[k] = "__CLEAR__"
        else:
            norm_d = normalize_date_str(v)
            if norm_d:
                for ak in alias_keys:
                    overrides.pop(ak, None)
                overrides[k] = norm_d

