def get_initial_master_products():
    if os.path.exists(DATA_FILE):
        try:
            with open(DATA_FILE, 'r', encoding='utf-8') as f:
                d = json.load(f)
                if isinstance(d, dict) and "master_products" in d:
                    return d["master_products"]
                elif isinstance(d, list):
                    return d
        except Exception:
            pass
    return []

