_admin_revoked_before = 0
_admin_last_iat_ms = 0
_admin_token_secret = os.urandom(32)

def get_effective_admin_pin():
    """우선순위: 환경변수 ADMIN_PIN -> 관리자 저장 커스텀 PIN -> 기본값 '1500'"""
    env_pin = os.environ.get("ADMIN_PIN", "").strip()
    if env_pin:
        return env_pin, "env"
    with data_lock:
        custom_pin = str(app_state.get("settings", {}).get("admin_pin_custom", "")).strip()
    if custom_pin:
        return custom_pin, "custom"
    return "1500", "default"

def issue_admin_token(ttl_seconds=43200):
    global _admin_last_iat_ms
    now_s = int(time.time())
    iat_ms = max(int(time.time() * 1000), _admin_revoked_before + 1)
    _admin_last_iat_ms = iat_ms
    exp = now_s + ttl_seconds
    pin, _ = get_effective_admin_pin()
    secret = hmac.new(_admin_token_secret, pin.encode('utf-8'), hashlib.sha256).digest()
    msg = f"{iat_ms}.{exp}"
    sig = hmac.new(secret, msg.encode("utf-8"), hashlib.sha256).hexdigest()
    return f"{iat_ms}.{exp}.{sig}", ttl_seconds

def verify_admin_token(token):
    if not token or str(token).count(".") != 2:
        return False
    try:
        iat_s, exp_s, sig = str(token).strip().split(".", 2)
        iat_ms = int(iat_s)
        exp = int(exp_s)
        now = int(time.time())
        if exp < now or iat_ms <= _admin_revoked_before:
            return False
        pin, _ = get_effective_admin_pin()
        secret = hmac.new(_admin_token_secret, pin.encode('utf-8'), hashlib.sha256).digest()
        expected = hmac.new(secret, f"{iat_s}.{exp_s}".encode("utf-8"), hashlib.sha256).hexdigest()
        return hmac.compare_digest(expected, sig)
    except Exception:
        return False

def require_admin(fn):
    @wraps(fn)
    def wrapper(*args, **kwargs):
        token = request.headers.get("X-Admin-Token", "").strip()
        if not verify_admin_token(token):
            return jsonify({
                "success": False,
                "code": "ADMIN_AUTH_REQUIRED",
                "message": "관리자 PIN 인증이 필요하거나 세션이 만료되었습니다."
            }), 401
        return fn(*args, **kwargs)
    return wrapper


def _manual_sales_readonly_product_provider():
    """Read-only snapshot of active master products for manual sales lookup."""
    with data_lock:
        masters = list(app_state.get("master_products") or [])
    catalog = {}
    for item in masters:
        if not isinstance(item, dict):
            continue
        code = str(item.get("seller_code") or "").strip()
        name = str(item.get("name") or item.get("seller_name") or "").strip()
        if code and name:
            catalog[code] = name
    return catalog


def _resolve_manual_sales_env_config():
    """
    Read only non-secret opt-in switch env vars for Manual Sales.
    Default is strictly OFF (MANUAL_SALES_ENABLED=False, MANUAL_SALES_STORAGE_MODE='off').
    Never reads DSN/credentials into app.config and never auto-enables sqlite_local.
    """
    raw_enabled = os.environ.get("MANUAL_SALES_ENABLED", "").strip().lower() in ("true", "1", "yes")
    raw_mode = os.environ.get("MANUAL_SALES_STORAGE_MODE", "").strip().lower()
    mode = "postgres" if raw_mode == "postgres" else "off"
    return raw_enabled, mode


