@app.before_request
def protect_management_data():
    # Protect aliases as well as API paths; the inventory sharing routes stay public.
    sensitive = request.path in (
        '/api/cash-flow/manual-transaction',
    )
    if sensitive and not verify_admin_token(request.headers.get('X-Admin-Token', '').strip()):
        return jsonify(success=False, code='ADMIN_AUTH_REQUIRED', message='관리자 PIN 인증이 필요합니다.'), 401


@app.after_request
def management_no_cache(response):
    if request.path in ('/dashboard_data.json', '/api/dashboard-data', '/api/download-pnl-excel') or request.path.startswith('/api/export/'):
        response.headers['Cache-Control'] = 'no-store'
        response.headers['Vary'] = 'X-Admin-Token'
    return response


@app.route('/api/export/<dataset>')
def export_management_csv(dataset):
    selectors = {
        'sales': ('sales_profit', 'transactions'),
        'cashflow': ('cash_flow', 'transactions'),
        'settlements': ('settlements', 'items'),
        'unmatched': ('sales_profit', 'unmatched_products'),
    }
    if dataset not in selectors:
        return jsonify(error='지원하지 않는 데이터셋입니다.'), 404
    path = app.config.get('DASHBOARD_DATA_FILE') or os.environ.get('DASHBOARD_DATA_FILE') or os.path.join(BASE_DIR, 'dashboard_data.json')
    if not os.path.isfile(path):
        return jsonify(error='대시보드 데이터를 먼저 생성하세요.'), 404
    with open(path, encoding='utf-8') as source:
        data = json.load(source)
    area, key = selectors[dataset]
    # Never silently export a truncated recent-transactions preview as full detail.
    if key not in data.get(area, {}):
        return jsonify(error='세부 데이터가 없습니다. 최신 exporter로 JSON을 재생성하세요.'), 409
    rows = data[area][key]
    if dataset == 'unmatched':
        columns = ['option_id', 'product_name', 'option_name', 'category', 'revenue', 'quantity', 'product_code', 'reason', 'source']
        rows = [dict(zip(columns, row)) for row in rows]
    else:
        defaults = {'sales': ['date', 'channel', 'product_name', 'quantity', 'revenue', 'cost', 'contribution_profit'],
                    'cashflow': ['transaction_id', 'date', 'customer', 'deposit_amount', 'withdrawal_amount'],
                    'settlements': ['customer', 'net_amount', 'paid_amount', 'outstanding_amount']}
        columns = list(dict.fromkeys(k for row in rows for k in row)) or defaults[dataset]
    def safe_cell(value):
        if value is None:
            return ''
        if isinstance(value, (list, dict)):
            value = json.dumps(value, ensure_ascii=False)
        if isinstance(value, str) and value.lstrip().startswith(('=', '+', '-', '@')):
            return "'" + value
        return value
    stream = io.StringIO(newline='')
    writer = csv.writer(stream)
    writer.writerow(columns)
    writer.writerows([safe_cell(row.get(k)) for k in columns] for row in rows)
    return Response(stream.getvalue().encode('utf-8-sig'), content_type='text/csv; charset=utf-8',
                    headers={'Content-Disposition': f'attachment; filename="{dataset}.csv"'})


_raw_inventory_signatures = {}
_raw_inventory_lock = threading.Lock()


def inventory_whitelist():
    from pathlib import Path
    root = str(Path(BASE_DIR).parent)
    if root not in sys.path:
        sys.path.insert(0, root)
    if 'C:/AI/경영관리' not in sys.path:
        sys.path.insert(0, 'C:/AI/경영관리')
    try:
        from scripts.channel_whitelist import load_whitelist
        candidate = app.config.get('CHANNEL_WHITELIST_FILE')
        if not candidate or not Path(candidate).exists():
            for p in [Path(BASE_DIR).parent / 'master_data/오키드상품정보.xlsx', Path(BASE_DIR) / 'master_data/오키드상품정보.xlsx', Path('C:/AI/경영관리/master_data/오키드상품정보.xlsx')]:
                if p.exists():
                    candidate = str(p)
                    break
        return load_whitelist(candidate)
    except (ImportError, Exception):
        try:
            from .cloud_storage import inventory_allowlist
        except ImportError:
            from cloud_storage import inventory_allowlist
        candidate = app.config.get('CHANNEL_WHITELIST_FILE')
        if not candidate or not Path(candidate).exists():
            for p in [Path(BASE_DIR).parent / 'master_data/오키드상품정보.xlsx', Path(BASE_DIR) / 'master_data/오키드상품정보.xlsx', Path('C:/AI/경영관리/master_data/오키드상품정보.xlsx')]:
                if p.exists():
                    candidate = str(p)
                    break
        return inventory_allowlist(candidate or (Path(BASE_DIR).parent / 'master_data/오키드상품정보.xlsx'))


def _restore_inventory_from_disk(need_gaemi=True, need_coupang=True):
    """로컬 영구 저장소(inventory_master_store.json) 또는 dashboard_data.json에서 재고 복구"""
    try:
        if os.path.exists(DATA_FILE):
            with open(DATA_FILE, 'r', encoding='utf-8') as f:
                saved = json.load(f)
                with data_lock:
                    if need_gaemi and saved.get('gaemi_inventory'):
                        app_state['gaemi_inventory'] = saved['gaemi_inventory']
                        need_gaemi = False
                    if need_coupang and saved.get('coupang_inventory'):
                        app_state['coupang_inventory'] = saved['coupang_inventory']
                        need_coupang = False
                    if saved.get('upload_timestamps'):
                        app_state.setdefault('upload_timestamps', {}).update(saved['upload_timestamps'])
    except Exception as exc:
        app.logger.warning('로컬 스토어에서 재고 복구 시도 실패: %s', exc)

    if need_gaemi or need_coupang:
        try:
            dashboard_file = app.config.get('DASHBOARD_DATA_FILE') or os.environ.get('DASHBOARD_DATA_FILE') or (Path(BASE_DIR) / 'dashboard_data.json')
            if os.path.exists(str(dashboard_file)):
                with open(str(dashboard_file), 'r', encoding='utf-8') as f:
                    db_data = json.load(f)
                    snaps = db_data.get('inventory_snapshots', {})
                    with data_lock:
                        if need_gaemi and snaps.get('gaemi'):
                            app_state['gaemi_inventory'] = snaps['gaemi']
                        if need_coupang and snaps.get('coupang'):
                            app_state['coupang_inventory'] = snaps['coupang']
        except Exception as exc:
            app.logger.warning('dashboard_data.json 재고 복구 실패: %s', exc)


def refresh_raw_inventory():
    """Select independently by filename date, then replace each complete snapshot."""
    from pathlib import Path
    candidate_folders = [
        Path(app.config.get('INVENTORY_RAW_DIR', '')) if app.config.get('INVENTORY_RAW_DIR') else None,
        Path(BASE_DIR).parent / 'raw_data' / 'inventory',
        Path(BASE_DIR) / 'raw_data' / 'inventory',
        Path('C:/AI/경영관리/raw_data/inventory'),
    ]
    folder = None
    for cand in candidate_folders:
        if cand and cand.exists() and cand.is_dir():
            folder = cand
            break

    with _raw_inventory_lock:
        whitelist = None
        master_stat = None
        try:
            whitelist = inventory_whitelist()
            master_p = Path(whitelist.get('path', ''))
            master_stat = master_p.stat() if master_p.exists() else None
        except Exception as exc:
            app.logger.warning('화이트리스트 로드 실패 (기존 재고 유지): %s', exc)

        did_parse_any = False
        if folder and folder.exists():
            for source, marker, parser, state_key in (
                ('gaemi', '3pl', parse_gaemi_rows, 'gaemi_inventory'),
                ('coupang', 'coupang', parse_coupang_rows, 'coupang_inventory'),
            ):
                candidates = []
                for path in folder.glob('*'):
                    pname = path.name.lower()
                    if source == 'gaemi':
                        if not any(k in pname for k in ('3pl', 'gaemi', '개미')):
                            continue
                    else:
                        if not any(k in pname for k in ('coupang', '쿠팡')):
                            continue
                    if path.suffix.lower() not in ('.xlsx', '.xls', '.csv'):
                        continue
                    try:
                        file_date = date.fromisoformat(path.name[:10])
                        stat = path.stat()
                        candidates.append((file_date, stat.st_mtime_ns, str(path), stat.st_size))
                    except (ValueError, OSError):
                        continue
                if not candidates:
                    continue
                file_date, mtime, path, size = max(candidates)
                path = Path(path)
                master_mtime = master_stat.st_mtime_ns if master_stat else 0
                master_size = master_stat.st_size if master_stat else 0
                wl_path = whitelist.get('path', '') if whitelist else ''
                signature = (str(path), mtime, size, wl_path, master_mtime, master_size)
                if _raw_inventory_signatures.get(source) == signature:
                    continue
                try:
                    if path.suffix.lower() == '.csv':
                        try:
                            text = path.read_text(encoding='utf-8-sig')
                        except UnicodeDecodeError:
                            text = path.read_text(encoding='cp949')
                        parsed = parser(list(csv.reader(io.StringIO(text))))
                    else:
                        root = str(Path(BASE_DIR).parent)
                        if root not in sys.path:
                            sys.path.insert(0, root)
                        try:
                            from scripts.common import read_excel_sheets
                        except ImportError:
                            try:
                                from .cloud_storage import read_inventory_sheets as read_excel_sheets
                            except ImportError:
                                from cloud_storage import read_inventory_sheets as read_excel_sheets
                        parsed = {}
                        for _, rows in read_excel_sheets(path):
                            parsed = parser(rows)
                            if parsed:
                                break
                    if not parsed:
                        raise ValueError('재고 헤더 또는 유효 행을 찾을 수 없습니다.')
                    if whitelist:
                        allowed = whitelist.get('gaemi') if source == 'gaemi' else whitelist.get('coupang')
                        if allowed:
                            parsed = {key: value for key, value in parsed.items() if str(key).strip() in allowed}
                    with data_lock:
                        if source == 'gaemi':
                            apply_fifo_deduction_on_gaemi_upload(app_state[state_key], parsed)
                        app_state[state_key] = parsed
                        app_state.setdefault('upload_timestamps', {})[source] = str(file_date)
                        app_state.setdefault('raw_inventory_sources', {})[source] = str(path)
                    _raw_inventory_signatures[source] = signature
                    did_parse_any = True
                except Exception as exc:
                    app.logger.warning('최신 재고 파일 로드 실패 %s: %s', path, exc)

        if did_parse_any:
            try:
                _write_local_snapshot(build_state_snapshot())
            except Exception as e:
                app.logger.warning('스냅샷 로컬 저장 오류: %s', e)

        if not app.testing and 'unittest' not in sys.modules:
            with data_lock:
                need_gaemi = not bool(app_state.get('gaemi_inventory'))
                need_coupang = not bool(app_state.get('coupang_inventory'))
            if need_gaemi or need_coupang:
                _restore_inventory_from_disk(need_gaemi=need_gaemi, need_coupang=need_coupang)

# -------------------------------------------------------------
# Google Drive (Google Apps Script 웹앱) 영구 저장/복원 브리지
# -------------------------------------------------------------
def get_gas_config():
    url = os.environ.get("GOOGLE_APPS_SCRIPT_URL", "").strip()
    token = os.environ.get("GOOGLE_APPS_SCRIPT_TOKEN", "").strip()
    configured = bool(url and token)
    return {"configured": configured, "url": url, "token": token}

def _call_gas_bridge(action, payload=None, timeout=20, retries=1, retry_delays=(0.8, 1.5), force=False):
    cfg = get_gas_config()
    if not cfg["configured"]:
        return {"success": False, "error": "Google Apps Script 환경변수(GOOGLE_APPS_SCRIPT_URL, GOOGLE_APPS_SCRIPT_TOKEN)가 설정되지 않았습니다."}

    body = {
        "token": cfg["token"],
        "action": action
    }
    if payload is not None:
        body["payload"] = payload
    if force:
        body["force"] = True

    data_bytes = json.dumps(body, ensure_ascii=False).encode("utf-8")
    last_exc = None
    attempts = max(1, int(retries) + 1)

    for attempt in range(attempts):
        try:
            req = urllib.request.Request(
                cfg["url"],
                data=data_bytes,
                headers={
                    "Content-Type": "application/json; charset=utf-8",
                    "User-Agent": "Iljeomodo-Inventory/2.0"
                },
                method="POST"
            )
            cj = http.cookiejar.CookieJar()
            opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj))
            with opener.open(req, timeout=timeout) as resp:
                raw = resp.read().decode("utf-8", errors="replace")
                res = json.loads(raw)
            if isinstance(res, dict) and not res.get("success"):
                err_txt = str(res.get("error", "")).lower()
                is_transient = any(k in err_txt for k in ("lock", "timeout", "exceeded", "busy", "too many", "try again"))
                if is_transient and attempt + 1 < attempts:
                    time.sleep(retry_delays[min(attempt, len(retry_delays) - 1)])
                    continue
            return res
        except urllib.error.HTTPError as e:
            last_exc = e
            if e.code in (429, 500, 502, 503, 504) and attempt + 1 < attempts:
                time.sleep(retry_delays[min(attempt, len(retry_delays) - 1)])
                continue
            raise
        except Exception as e:
            last_exc = e
            if attempt + 1 < attempts:
                time.sleep(retry_delays[min(attempt, len(retry_delays) - 1)])
                continue
            raise
    if last_exc:
        raise last_exc
    return {"success": False, "error": "Drive bridge 요청 실패"}

def normalize_hidden_unmapped_key(raw_key):
    s = _clean_cell_str(raw_key)
    if "::" not in s:
        return ""
    ch, rest = s.split("::", 1)
    ch = ch.strip().lower()
    rest = rest.strip()
    if ch == "sales":
        code = rest.upper()
        return f"sales::{code}" if code else ""
    elif ch == "gaemi":
        if "||" in rest:
            g_code, opt_name = rest.split("||", 1)
            g_code = g_code.strip().upper()
            opt_name = opt_name.strip()
        else:
            g_code = rest.strip().upper()
            opt_name = ""
        return f"gaemi::{g_code}||{opt_name}" if g_code else ""
    elif ch == "coupang":
        oid = rest.strip()
        return f"coupang::{oid}" if oid else ""
    return ""

def sanitize_hidden_unmapped_list(raw_list):
    if not isinstance(raw_list, list):
        return []
    seen = set()
    out = []
    for item in raw_list:
        nk = normalize_hidden_unmapped_key(item)
        if nk and nk not in seen:
            seen.add(nk)
            out.append(nk)
    return out

def _unhide_mapped_keys_locked(record):
    """방금 마스터 상품에 매핑된 코드는 미매핑 숨김 목록에서 자동 해제(data_lock 보유 상태에서 호출)"""
    hidden_list = app_state.get("hidden_unmapped_codes")
    if not isinstance(hidden_list, list) or not hidden_list or not isinstance(record, dict):
        return
    if record.get("is_active") is False or is_s_product_code(record.get("seller_code")):
        return
    to_remove = set()
    seller_up = str(record.get("seller_code", "")).strip().upper()
    if isinstance(record.get("sales_codes"), list):
        sc_list = record.get("sales_codes")
    else:
        sc_list = [seller_up] if seller_up else []
    for sc in sc_list:
        sc_up = str(sc or "").strip().upper()
        if sc_up:
            to_remove.add(f"sales::{sc_up}")

    wildcard_gaemi_codes = set()
    for rule in (record.get("gaemi_mappings") or []):
        if not isinstance(rule, dict):
            continue
        gc = _clean_cell_str(rule.get("gaemi_code") or rule.get("code") or "").upper()
        opt = _clean_cell_str(rule.get("option_name", ""))
        if not gc:
            continue
        if opt in ("", "*"):
            wildcard_gaemi_codes.add(gc)
        else:
            to_remove.add(f"gaemi::{gc}||{opt}")

    for o in (record.get("options") or []):
        if not isinstance(o, dict):
            continue
        oid = str(o.get("id", "")).strip()
        if oid:
            to_remove.add(f"coupang::{oid}")

    if not to_remove and not wildcard_gaemi_codes:
        return

    cleaned = []
    for hk in hidden_list:
        if hk in to_remove:
            continue
        if hk.startswith("gaemi::") and wildcard_gaemi_codes:
            body = hk[7:]
            gc_part = body.split("||", 1)[0].strip().upper()
            if gc_part in wildcard_gaemi_codes:
                continue
        cleaned.append(hk)
    app_state["hidden_unmapped_codes"] = cleaned

def build_state_snapshot():
    with data_lock:
        return {
            "title": "일쩜오도 재고현황",
            "schema_version": 2,
            "master_products": copy.deepcopy(app_state["master_products"]),
            "b2b_mappings": copy.deepcopy(app_state["b2b_mappings"]),
            "lot_expiry_overrides": copy.deepcopy(app_state["lot_expiry_overrides"]),
            "hidden_unmapped_codes": sanitize_hidden_unmapped_list(app_state.get("hidden_unmapped_codes", [])),
            "settings": copy.deepcopy(app_state["settings"]),
            "gaemi_inventory": copy.deepcopy(app_state["gaemi_inventory"]),
            "coupang_inventory": copy.deepcopy(app_state["coupang_inventory"]),
            "sales_inventory": copy.deepcopy(app_state["sales_inventory"]),
            "last_updated": app_state.get("data_uploaded_at", ""),
            "data_uploaded_at": app_state.get("data_uploaded_at", ""),
            "upload_timestamps": copy.deepcopy(app_state.get("upload_timestamps", {})),
            "saved_at": now_kst().strftime("%Y-%m-%d %H:%M:%S")
        }

def _write_local_snapshot(snapshot):
    tmp_path = DATA_FILE + ".tmp"
    with open(tmp_path, 'w', encoding='utf-8') as f:
        json.dump(snapshot, f, ensure_ascii=False, indent=2)
    os.replace(tmp_path, DATA_FILE)

def _apply_loaded_state(saved):
    if not isinstance(saved, dict):
        return False
    with data_lock:
        if "master_products" in saved and isinstance(saved["master_products"], list):
            app_state["master_products"] = saved["master_products"]
        if "b2b_mappings" in saved and isinstance(saved["b2b_mappings"], dict):
            app_state["b2b_mappings"] = saved["b2b_mappings"]
        if "lot_expiry_overrides" in saved and isinstance(saved["lot_expiry_overrides"], dict):
            app_state["lot_expiry_overrides"] = saved["lot_expiry_overrides"]
        if isinstance(saved.get("hidden_unmapped_codes"), list):
            app_state["hidden_unmapped_codes"] = sanitize_hidden_unmapped_list(saved.get("hidden_unmapped_codes"))
        else:
            app_state["hidden_unmapped_codes"] = []
        if "settings" in saved and isinstance(saved["settings"], dict):
            merged_settings = copy.deepcopy(DEFAULT_SETTINGS)
            merged_settings.update(saved["settings"])
            app_state["settings"] = merged_settings
        if "gaemi_inventory" in saved and isinstance(saved["gaemi_inventory"], dict):
            if saved["gaemi_inventory"] or not app_state.get("gaemi_inventory"):
                app_state["gaemi_inventory"] = saved["gaemi_inventory"]
        if "coupang_inventory" in saved and isinstance(saved["coupang_inventory"], dict):
            if saved["coupang_inventory"] or not app_state.get("coupang_inventory"):
                app_state["coupang_inventory"] = saved["coupang_inventory"]
        if "sales_inventory" in saved and isinstance(saved["sales_inventory"], dict):
            if saved["sales_inventory"] or not app_state.get("sales_inventory"):
                app_state["sales_inventory"] = saved["sales_inventory"]
        if "data_uploaded_at" in saved:
            du = str(saved.get("data_uploaded_at") or "").strip()
            app_state["data_uploaded_at"] = du
            app_state["last_updated"] = du
        else:
            app_state["data_uploaded_at"] = ""
            app_state["last_updated"] = ""
        if isinstance(saved.get("upload_timestamps"), dict):
            app_state["upload_timestamps"] = dict(saved["upload_timestamps"])
        else:
            app_state["upload_timestamps"] = {}
    return True

def _reset_blocked_flags_locked():
    _blocked_state_flags["admin_mutated"] = False
    _blocked_state_flags["uploaded_sources"].clear()
    _blocked_state_flags["fresh_uploads"].clear()

def _cancel_boot_recovery():
    global _boot_recovery_gen
    with _boot_recovery_lock:
        _boot_recovery_gen += 1
        _boot_recovery_cancel.set()

def sync_to_drive(wait=False, force=False):
    cfg = get_gas_config()
    if not cfg["configured"]:
        drive_sync_state["configured"] = False
        drive_sync_state["status"] = "disabled"
        drive_sync_state["sync_blocked"] = False
        drive_sync_state["boot_restore_failed"] = False
        return copy.deepcopy(drive_sync_state)

    drive_sync_state["configured"] = True

    if drive_sync_state.get("sync_blocked") and not force:
        err_msg = "부팅 시 Google Drive 최신 데이터를 복원하지 못해 기존 Drive 백업 보호를 위해 자동 덮어쓰기가 차단되었습니다."
        drive_sync_state["status"] = "blocked"
        drive_sync_state["last_error"] = err_msg
        add_log(f"🛑 {err_msg}")
        return copy.deepcopy(drive_sync_state)

    def _do_sync():
        with drive_sync_lock:
            if drive_sync_state.get("sync_blocked") and not force:
                drive_sync_state["status"] = "blocked"
                return
            drive_sync_state["status"] = "syncing"
            try:
                snap = build_state_snapshot()
                masters_list = snap.get("master_products")
                if not force and (not isinstance(masters_list, list) or len(masters_list) == 0):
                    err_msg = "마스터 상품 목록이 비어 있어 Google Drive 덮어쓰기를 중단했습니다."
                    drive_sync_state["status"] = "blocked"
                    drive_sync_state["sync_blocked"] = True
                    drive_sync_state["last_error"] = err_msg
                    add_log(f"🛑 {err_msg}")
                    return

                res = _call_gas_bridge("save", payload=snap, timeout=20, retries=1, retry_delays=(0.8,), force=force)
                if res.get("success"):
                    drive_sync_state["status"] = "synced"
                    drive_sync_state["sync_blocked"] = False
                    drive_sync_state["boot_restore_failed"] = False
                    with data_lock:
                        _reset_blocked_flags_locked()
                    drive_sync_state["last_synced_at"] = now_kst().strftime("%Y-%m-%d %H:%M:%S")
                    drive_sync_state["last_error"] = ""
                    if res.get("fileId"):
                        drive_sync_state["file_id"] = res["fileId"]
                else:
                    drive_sync_state["status"] = "blocked" if drive_sync_state.get("sync_blocked") else "error"
                    drive_sync_state["last_error"] = res.get("error", "알 수 없는 Drive 응답 오류")
                    add_log(f"⚠️ Google Drive 동기화 실패: {drive_sync_state['last_error']}")
            except Exception as e:
                drive_sync_state["status"] = "blocked" if drive_sync_state.get("sync_blocked") else "error"
                drive_sync_state["last_error"] = str(e)
                add_log(f"⚠️ Google Drive 동기화 예외: {e}")

    if wait:
        _do_sync()
    else:
        drive_sync_state["status"] = "syncing"
        threading.Thread(target=_do_sync, daemon=True).start()
    return copy.deepcopy(drive_sync_state)

def pull_from_drive(timeout=20, retries=1, retry_delays=(0.8, 1.5)):
    cfg = get_gas_config()
    if not cfg["configured"]:
        drive_sync_state["configured"] = False
        drive_sync_state["status"] = "disabled"
        return {"success": False, "exists": False, "error": "Google Apps Script 미설정"}

    drive_sync_state["configured"] = True
    try:
        with drive_sync_lock:
            res = _call_gas_bridge("load", timeout=timeout, retries=retries, retry_delays=retry_delays)
        if not res.get("success"):
            err = res.get("error", "Drive 조회 실패")
            drive_sync_state["status"] = "blocked" if drive_sync_state.get("sync_blocked") else "error"
            drive_sync_state["last_error"] = err
            return {"success": False, "exists": False, "error": err}

        if res.get("exists") and isinstance(res.get("data"), dict):
            remote_data = res["data"]
            remote_masters = remote_data.get("master_products")
            if not isinstance(remote_masters, list) or len(remote_masters) == 0:
                err = "Google Drive 백업 데이터에 유효한 master_products 목록이 없어 복원을 중단했습니다."
                drive_sync_state["status"] = "blocked" if drive_sync_state.get("sync_blocked") else "error"
                drive_sync_state["last_error"] = err
                return {"success": False, "exists": True, "error": err}
            _apply_loaded_state(remote_data)
            with data_lock:
                _reset_blocked_flags_locked()
            _write_local_snapshot(build_state_snapshot())
            now_s = now_kst().strftime("%Y-%m-%d %H:%M:%S")
            drive_sync_state["status"] = "synced"
            drive_sync_state["sync_blocked"] = False
            drive_sync_state["boot_restore_failed"] = False
            drive_sync_state["last_loaded_at"] = now_s
            drive_sync_state["last_synced_at"] = now_s
            drive_sync_state["last_error"] = ""
            if res.get("fileId"):
                drive_sync_state["file_id"] = res["fileId"]
            return {"success": True, "exists": True, "fileId": res.get("fileId", "")}
        else:
            drive_sync_state["status"] = "idle"
            drive_sync_state["sync_blocked"] = False
            drive_sync_state["boot_restore_failed"] = False
            return {"success": True, "exists": False}
    except Exception as e:
        drive_sync_state["status"] = "blocked" if drive_sync_state.get("sync_blocked") else "error"
        drive_sync_state["last_error"] = str(e)
        return {"success": False, "exists": False, "error": str(e)}

def _attempt_boot_drive_recovery_once():
    """부팅 복원 실패로 잠긴 상태에서 백그라운드 자동 복구 1회 시도 (관리자 수동 수정 없을 때만)"""
    if not drive_sync_state.get("sync_blocked"):
        return True
    cfg = get_gas_config()
    if not cfg["configured"]:
        return False

    with data_lock:
        if _blocked_state_flags.get("admin_mutated"):
            return False
        uploaded_sources = set(_blocked_state_flags.get("uploaded_sources") or ())
        fresh_uploads = copy.deepcopy(_blocked_state_flags.get("fresh_uploads") or {})
        local_ts = copy.deepcopy(app_state.get("upload_timestamps") or {})
        local_data_uploaded_at = str(app_state.get("data_uploaded_at") or "").strip()

    try:
        with drive_sync_lock:
            res = _call_gas_bridge("load", timeout=20, retries=0)
        if not res.get("success"):
            return False

        if res.get("exists") and isinstance(res.get("data"), dict):
            remote_data = res["data"]
            remote_masters = remote_data.get("master_products")
            if not isinstance(remote_masters, list) or len(remote_masters) == 0:
                return False

            # 재확인: Drive load 통신 중 관리자 수정이 발생했는지 체크
            with data_lock:
                if _blocked_state_flags.get("admin_mutated"):
                    return False
                uploaded_sources = set(_blocked_state_flags.get("uploaded_sources") or uploaded_sources)
                fresh_uploads = copy.deepcopy(_blocked_state_flags.get("fresh_uploads") or fresh_uploads)
                local_ts = copy.deepcopy(app_state.get("upload_timestamps") or local_ts)
                local_data_uploaded_at = str(app_state.get("data_uploaded_at") or local_data_uploaded_at).strip()

            _apply_loaded_state(remote_data)

            had_fresh_uploads = False
            if uploaded_sources and fresh_uploads:
                with data_lock:
                    if "gaemi" in fresh_uploads:
                        old_gaemi = copy.deepcopy(app_state["gaemi_inventory"])
                        apply_fifo_deduction_on_gaemi_upload(old_gaemi, fresh_uploads["gaemi"])
                        app_state["gaemi_inventory"] = copy.deepcopy(fresh_uploads["gaemi"])
                        had_fresh_uploads = True
                    if "coupang" in fresh_uploads:
                        app_state["coupang_inventory"].update(copy.deepcopy(fresh_uploads["coupang"]))
                        had_fresh_uploads = True
                    if "sales" in fresh_uploads:
                        app_state["sales_inventory"] = copy.deepcopy(fresh_uploads["sales"])
                        had_fresh_uploads = True
                    if had_fresh_uploads:
                        ts_map = app_state.setdefault("upload_timestamps", {})
                        for src in uploaded_sources:
                            if src in local_ts:
                                ts_map[src] = local_ts[src]
                        if local_data_uploaded_at:
                            app_state["data_uploaded_at"] = local_data_uploaded_at
                            app_state["last_updated"] = local_data_uploaded_at
                    _reset_blocked_flags_locked()
            else:
                with data_lock:
                    _reset_blocked_flags_locked()

            drive_sync_state["sync_blocked"] = False
            drive_sync_state["boot_restore_failed"] = False
            _write_local_snapshot(build_state_snapshot())

            if had_fresh_uploads:
                sync_to_drive(wait=True)
            else:
                now_s = now_kst().strftime("%Y-%m-%d %H:%M:%S")
                drive_sync_state["status"] = "synced"
                drive_sync_state["last_loaded_at"] = now_s
                drive_sync_state["last_synced_at"] = now_s
                drive_sync_state["last_error"] = ""
                if res.get("fileId"):
                    drive_sync_state["file_id"] = res["fileId"]

            add_log("☁️ [자동 복구 완료] Google Drive 최신 데이터를 복원하고 보호 잠금을 해제했습니다.")
            return True
        elif not res.get("exists"):
            drive_sync_state["sync_blocked"] = False
            drive_sync_state["boot_restore_failed"] = False
            drive_sync_state["status"] = "idle"
            return True
    except Exception:
        return False
    return False

def _schedule_boot_drive_recovery(delays=(3.0, 6.0, 12.0)):
    if app.testing or os.environ.get("ILJEOMODO_SKIP_BG_RECOVERY") == "1":
        return
    global _boot_recovery_gen
    with _boot_recovery_lock:
        _boot_recovery_gen += 1
        my_gen = _boot_recovery_gen
        _boot_recovery_cancel.clear()

    def _worker():
        for delay in delays:
            if _boot_recovery_cancel.wait(delay):
                return
            with _boot_recovery_lock:
                if _boot_recovery_gen != my_gen:
                    return
            if _attempt_boot_drive_recovery_once():
                return

    threading.Thread(target=_worker, daemon=True).start()

# 영구 데이터 로드/저장
def load_state():
    global app_state
    _cancel_boot_recovery()
    with data_lock:
        _reset_blocked_flags_locked()

    if os.path.exists(DATA_FILE):
        try:
            with open(DATA_FILE, 'r', encoding='utf-8') as f:
                saved = json.load(f)
                if _apply_loaded_state(saved):
                    add_log("💾 저장된 일쩜오도 재고 및 매핑 데이터를 불러왔습니다.")
        except Exception as e:
            add_log(f"⚠️ 로컬 데이터 로드 실패: {e}")

    cfg = get_gas_config()
    drive_sync_state["configured"] = cfg["configured"]
    drive_sync_state["sync_blocked"] = False
    drive_sync_state["boot_restore_failed"] = False

    if cfg["configured"] and os.environ.get("ILJEOMODO_SKIP_BOOT_DRIVE") != "1":
        res = pull_from_drive(timeout=18, retries=1, retry_delays=(1.0,))
        if res.get("success") and res.get("exists"):
            add_log("☁️ Google Drive 영구 저장소에서 최신 관리자/재고 데이터를 자동 복원했습니다.")
        elif res.get("success") and not res.get("exists"):
            add_log("☁️ Google Drive 최초 연결 완료: 초기 기준 데이터를 Drive에 업로드합니다.")
            sync_to_drive(wait=False)
        else:
            drive_sync_state["sync_blocked"] = True
            drive_sync_state["boot_restore_failed"] = True
            drive_sync_state["status"] = "blocked"
            drive_sync_state["last_error"] = res.get("error") or "초기 Google Drive 복원 실패"
            add_log(f"🛑 Google Drive 초기 복원 실패 (기존 Drive 백업 보호를 위해 자동 덮어쓰기 차단): {res.get('error')}")
            _schedule_boot_drive_recovery()
    elif not cfg["configured"]:
        drive_sync_state["status"] = "disabled"

    if os.environ.get('ILJEOMODO_SKIP_BOOT_DRIVE') != '1':
        refresh_cloud_files(force=True)

load_state()

def save_state(sync_drive=True, wait_drive=False, is_admin_mutation=False):
    if is_admin_mutation and drive_sync_state.get("sync_blocked"):
        with data_lock:
            _blocked_state_flags["admin_mutated"] = True

    try:
        snapshot = build_state_snapshot()
        _write_local_snapshot(snapshot)
    except Exception as e:
        add_log(f"⚠️ 로컬 데이터 저장 오류: {e}")

    if sync_drive:
        return sync_to_drive(wait=wait_drive)
    return copy.deepcopy(drive_sync_state)

