# -------------------------------------------------------------
# 파서 1: 개미창고 CSV/엑셀 파서 (소비기한 및 잔여 D-Day 자동 분석)
# -------------------------------------------------------------
def parse_gaemi_rows(rows):
    """
    개미창고 파일 컬럼: 번호, 상품코드, 상품명, 옵션명, 상태, 입고량, 출고량, 재고량, 등록일
    옵션명에서 소비기한(예: 27.03.28, 2027-04-30 등)을 자동 추출하여 잔여일(D-Day) 산출
    """
    if not rows or len(rows) < 2:
        return {}

    header_idx = -1
    for i, r in enumerate(rows[:15]):
        if not isinstance(r, (list, tuple)):
            continue
        line_str = " ".join([_clean_cell_str(c) for c in r])
        if "상품코드" in line_str and "재고량" in line_str:
            header_idx = i
            break

    if header_idx == -1:
        return {}

    headers = [_clean_cell_str(c) for c in rows[header_idx]]
    col_code = next((i for i, h in enumerate(headers) if "상품코드" in h), 1)
    col_pname = next((i for i, h in enumerate(headers) if "상품명" in h), 2)
    col_oname = next((i for i, h in enumerate(headers) if "옵션명" in h), 3)
    col_stock = next((i for i, h in enumerate(headers) if "재고량" in h), 7)
    col_reg = next((i for i, h in enumerate(headers) if "등록일" in h), 8)

    gaemi_dict = {}
    today = today_kst()

    for r in rows[header_idx + 1:]:
        if not isinstance(r, (list, tuple)) or len(r) <= max(col_code, col_stock):
            continue
        code = _clean_id_cell(r[col_code])
        if not code or code == "상품코드":
            continue

        pname = _clean_cell_str(r[col_pname]) if len(r) > col_pname else ""
        oname = _clean_cell_str(r[col_oname]) if len(r) > col_oname else ""
        stock = _clean_int_cell(r[col_stock])
        reg_raw = r[col_reg] if len(r) > col_reg else ""
        reg_date = normalize_gaemi_reg_date(reg_raw)

        # 소비기한 추출 및 잔여일수(D-Day) 계산
        exp_d = extract_expiry_date(oname)
        exp_str = exp_d.strftime("%Y-%m-%d") if exp_d else ""
        days_left = (exp_d - today).days if exp_d else None

        if code not in gaemi_dict:
            gaemi_dict[code] = []

        gaemi_dict[code].append({
            "product_name": pname,
            "option_name": oname,
            "stock": stock,
            "reg_date": reg_date,
            "expiry_date": exp_str,
            "days_left": days_left
        })

    return gaemi_dict

# -------------------------------------------------------------
# 파서 2: 쿠팡 윙 재고 건강도 CSV 파서
# -------------------------------------------------------------

def _inventory_metric(value):
    if value is None or str(value).strip() in ("", "-"):
        return None
    if not re.fullmatch(r"-?\d+(?:\.\d+)?", str(value).replace(",", "").strip()):
        return None
    return _clean_int_cell(value)


def _inventory_add(a, b):
    return None if a is None or b is None else a + b


def _inventory_scale(value, multiplier):
    return None if value is None else value * multiplier


def parse_coupang_rows(rows):
    """
    쿠팡 파일: 등록상품 ID, 옵션 ID, 등록상품명, 옵션명, 상품등급(G열: NEW / 반품...), 판매가능재고 (실시간 기준), 입고예정재고, 최근 판매수량(지난 7일, 지난 30일), 예상 소진일(DOC)
    """
    if not rows or len(rows) < 2:
        return {}

    header_idx = -1
    for i, r in enumerate(rows[:25]):
        if not isinstance(r, (list, tuple)):
            continue
        compact_cells = [re.sub(r"\s+", "", _clean_cell_str(c)) for c in r]
        line_compact = " ".join(compact_cells)
        if "옵션ID" in line_compact or "옵션번호" in line_compact:
            header_idx = i
            break

    if header_idx == -1:
        return {}

    raw_h1 = [_clean_cell_str(c) for c in rows[header_idx]]
    h1_compact = [re.sub(r"\s+", "", h) for h in raw_h1]
    prelim_oid = next((i for i, hc in enumerate(h1_compact) if "옵션ID" in hc or "옵션번호" in hc), 2)

    has_subheader = False
    raw_h2 = []
    if header_idx + 1 < len(rows) and isinstance(rows[header_idx + 1], (list, tuple)):
        r_next = rows[header_idx + 1]
        next_oid_val = _clean_id_cell(r_next[prelim_oid]) if len(r_next) > prelim_oid else ""
        if not (next_oid_val and next_oid_val.isdigit()):
            if any(_clean_cell_str(c) for c in r_next):
                has_subheader = True
                raw_h2 = [_clean_cell_str(c) for c in r_next]

    max_cols = max(len(raw_h1), len(raw_h2))
    headers = []
    for i in range(max_cols):
        p1 = raw_h1[i] if i < len(raw_h1) else ""
        p2 = raw_h2[i] if i < len(raw_h2) else ""
        if p1 and p2 and p2 not in p1:
            headers.append(f"{p1} {p2}".strip())
        else:
            headers.append(p1 or p2)

    headers_compact = [re.sub(r"\s+", "", h) for h in headers]

    col_oid = next((i for i, hc in enumerate(headers_compact) if "옵션ID" in hc), -1)
    if col_oid == -1:
        col_oid = next((i for i, hc in enumerate(headers_compact) if "옵션번호" in hc), 2)
    col_pname = next((i for i, hc in enumerate(headers_compact) if "등록상품명" in hc or "상품명" in hc), 4)
    col_oname = next((i for i, hc in enumerate(headers_compact) if "옵션명" in hc), 5)
    col_stock = next((i for i, hc in enumerate(headers_compact) if "판매가능재고" in hc), 7)
    col_inbound = next((i for i, hc in enumerate(headers_compact) if "입고예정재고" in hc), 8)

    col_sales7 = 12
    col_sales30 = 13
    col_doc = 14
    found_sales_qty = False
    found_doc = False

    for i, hc in enumerate(headers_compact):
        if not found_sales_qty and "판매수량" in hc:
            col_sales7 = i
            col_sales30 = i + 1
            found_sales_qty = True
        if not found_doc and "DOC" in hc.upper():
            col_doc = i
            found_doc = True
    if not found_doc:
        col_doc = next((i for i, hc in enumerate(headers_compact) if "소진일" in hc), 14)

    col_sku = next((i for i, hc in enumerate(headers_compact) if "SKUID" in hc.upper()), -1)
    col_winner = next((i for i, hc in enumerate(headers_compact) if "아이템위너" in hc), -1)

    used_cols = {col_oid, col_pname, col_oname, col_stock, col_inbound, col_sales7, col_sales30, col_doc}
    if col_sku >= 0:
        used_cols.add(col_sku)
    if col_winner >= 0:
        used_cols.add(col_winner)

    col_pid = next((i for i, hc in enumerate(headers_compact) if "등록상품ID" in hc), -1)
    if col_pid == -1 and len(headers) > 1 and 1 not in used_cols:
        col_pid = 1
    if col_pid >= 0:
        used_cols.add(col_pid)

    def _is_grade_col_excluded(hc):
        return any(bad in hc for bad in ("고객반품", "반품지난", "반품수", "반품률", "반품율"))

    col_grade = next(
        (i for i, hc in enumerate(headers_compact)
         if not _is_grade_col_excluded(hc) and ("상품등급" in hc or "품질등급" in hc or "재고등급" in hc)),
        -1
    )
    if col_grade == -1:
        col_grade = next(
            (i for i, hc in enumerate(headers_compact)
             if i not in used_cols and not _is_grade_col_excluded(hc)
             and (hc in ("등급", "상품상태", "재고상태", "아이템상태", "상태", "컨디션")
                  or hc.lower() in ("grade", "itemgrade", "condition", "status"))),
            -1
        )
    if col_grade == -1:
        col_grade = next(
            (i for i, hc in enumerate(headers_compact)
             if i not in used_cols and not _is_grade_col_excluded(hc) and "등급" in hc),
            -1
        )
    if col_grade == -1:
        col_grade = next(
            (i for i, hc in enumerate(headers_compact)
             if i not in used_cols and not _is_grade_col_excluded(hc) and ("상태" in hc or "컨디션" in hc)),
            -1
        )
    if col_grade == -1 and len(headers) > 6 and 6 not in used_cols:
        col_grade = 6

    data_start_idx = header_idx + (2 if has_subheader else 1)
    updated_label = now_kst().strftime("%m-%d %H:%M")
    coupang_dict = {}
    for r in rows[data_start_idx:]:
        if not isinstance(r, (list, tuple)) or len(r) <= col_oid:
            continue
        oid = _clean_id_cell(r[col_oid])
        if not oid or not oid.isdigit():
            continue

        pid = _clean_id_cell(r[col_pid]) if (col_pid >= 0 and len(r) > col_pid) else ""
        pname = _clean_cell_str(r[col_pname]) if (col_pname >= 0 and len(r) > col_pname) else ""
        oname = _clean_cell_str(r[col_oname]) if (col_oname >= 0 and len(r) > col_oname) else ""
        grade = _clean_cell_str(r[col_grade]) if (col_grade >= 0 and len(r) > col_grade) else ""
        is_return = ("반품" in grade) or ("return" in grade.lower())
        stock = _clean_int_cell(r[col_stock]) if len(r) > col_stock else 0
        inbound = _clean_int_cell(r[col_inbound]) if len(r) > col_inbound else 0
        sales7 = _inventory_metric(r[col_sales7]) if len(r) > col_sales7 else None
        sales30 = _inventory_metric(r[col_sales30]) if len(r) > col_sales30 else None
        doc = _inventory_metric(r[col_doc]) if len(r) > col_doc else None

        if sales7 is None or sales30 is None:
            doc = None
        coupang_dict[oid] = {
            "product_id": pid,
            "product_name": pname,
            "option_name": oname,
            "grade": grade,
            "is_return": is_return,
            "stock": stock,
            "inbound": inbound,
            "sales_7d": sales7,
            "sales_30d": sales30,
            "doc": doc,
            "updated_at": updated_label
        }

    return coupang_dict

# -------------------------------------------------------------
# 파서 3: 쿠팡외 통합 매출 데이터 CSV 파서 (7일 & 30일 분리 집계)
# -------------------------------------------------------------
def parse_order_datetime(date_str):
    if date_str is None or isinstance(date_str, bool):
        return None
    dt_serial = excel_serial_to_datetime(date_str)
    if dt_serial is not None:
        return dt_serial
    s = _clean_cell_str(date_str)
    if not s:
        return None
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d', '%Y.%m.%d %H:%M:%S', '%Y.%m.%d', '%Y/%m/%d %H:%M:%S', '%Y/%m/%d'):
        try:
            return datetime.strptime(s, fmt)
        except Exception:
            pass
    m = re.search(r'(\d{4})[.\-/](\d{1,2})[.\-/](\d{1,2})(?:[ T]+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?', s)
    if m:
        try:
            return datetime(
                int(m.group(1)), int(m.group(2)), int(m.group(3)),
                int(m.group(4) or 0), int(m.group(5) or 0), int(m.group(6) or 0)
            )
        except Exception:
            pass
    return None

def parse_sales_rows(rows):
    """
    매출정보 CSV:
    주문일, 묶음번호, 쇼핑몰, 온라인상품명, 주문수량, 금액, 할인금액, 배송비, 실결제금액, 수령자명, 배송완료일, 세트코드, 판매자관리코드
    현재로부터 30일간의 주문 데이터에서 최신 주문일 기준 직전 7일 출고량과 30일 전체 출고량을 분리 산출
    """
    if not rows or len(rows) < 2:
        return {}

    header_idx = -1
    for i, r in enumerate(rows[:15]):
        if not isinstance(r, (list, tuple)):
            continue
        line_str = " ".join([_clean_cell_str(c) for c in r])
        if "판매자관리코드" in line_str or "상품관리코드" in line_str or "주문수량" in line_str or "온라인상품명" in line_str:
            header_idx = i
            break

    if header_idx == -1:
        return {}

    headers = [_clean_cell_str(c) for c in rows[header_idx]]
    col_code = next((i for i, h in enumerate(headers) if "판매자관리코드" in h or "상품관리코드" in h or "판매자코드" in h), -1)
    if col_code == -1:
        col_code = next((i for i, h in enumerate(headers) if "관리코드" in h), -1)
    col_qty = next((i for i, h in enumerate(headers) if "주문수량" in h or "수량" in h), 4)
    col_date = next((i for i, h in enumerate(headers) if "주문일" in h), 0)
    col_mall = next((i for i, h in enumerate(headers) if "쇼핑몰" in h), 2)
    col_name = next((i for i, h in enumerate(headers) if "상품명" in h), 3)

    if col_code == -1:
        col_code = len(headers) - 1

    parsed_entries = []
    valid_dates = []

    for r in rows[header_idx + 1:]:
        if not isinstance(r, (list, tuple)) or len(r) <= max(col_code, col_qty):
            continue
        code = _clean_id_cell(r[col_code]).upper()
        if not code or code in ("판매자관리코드", "상품관리코드", "판매자코드", "관리코드"):
            continue
        name = _clean_cell_str(r[col_name]) if len(r) > col_name else ""
        mall = _clean_cell_str(r[col_mall]) if len(r) > col_mall else ""
        raw_date = r[col_date] if len(r) > col_date else ""
        dt = parse_order_datetime(raw_date)
        date_s = normalize_gaemi_reg_date(raw_date) if excel_serial_to_datetime(raw_date) is not None else _clean_cell_str(raw_date)
        qty = _clean_int_cell(r[col_qty])

        if dt:
            valid_dates.append(dt)

        parsed_entries.append({
            "code": code,
            "name": name,
            "mall": mall,
            "date_s": date_s,
            "dt": dt,
            "qty": qty
        })

    # 최신 주문일 기준 최근 7일 컷오프 (기준 시점)
    max_dt = max(valid_dates) if valid_dates else now_kst().replace(tzinfo=None)
    cutoff_7d = max_dt - timedelta(days=7)

    sales_dict = {}
    for entry in parsed_entries:
        code = entry["code"]
        qty = entry["qty"]
        dt = entry["dt"]

        if code not in sales_dict:
            sales_dict[code] = {
                "total_7d": 0,
                "total_30d": 0,
                "orders": []
            }

        # 30일 전체 출고량 합산
        sales_dict[code]["total_30d"] += qty

        # 직전 7일 출고량 합산
        if dt is None or dt >= cutoff_7d:
            sales_dict[code]["total_7d"] += qty

        sales_dict[code]["orders"].append({
            "date": entry["date_s"],
            "qty": qty,
            "mall": entry["mall"],
            "name": entry["name"]
        })

    return sales_dict

